});

await aniLink.anilist.mutation.saveThread({
  id: 1,
  title: 'Hello, world!',
  body: 'Hello, world!',
  categories: [],
  mediaCategories: [],
  sticky: false,
  locked: false,
  asHtml: true,
});

await aniLink.anilist.mutation.saveThreadComment({
  id: 1,
  threadId: 1,
  parentCommentId: 0,
  comment: 'Hello, world!',
  locked: false,
  asHtml: true,
});

const api = new AniLink({ mal: { accessToken: "mal-token" } }).mal;
const results = await api.anime.search(
  { q: "one piece" },
  { fields: ["id", "title", "main_picture"] }
);
console.log(results.data[0]?.node.title);

const api = new AniLink({ mal: { accessToken: "mal-token" } }).mal;
const season = await api.anime.seasonal(
  { year: 2024, season: "winter" },
  { fields: ["id", "title", "main_picture"] }
);
console.log(season.data[0]?.node.title);

const api = new AniLink({ mal: { accessToken: "mal-token" } }).mal;
